from pathlib import Path
D=Path('docs/brand-identity-reconstruction')
css='''*{box-sizing:border-box}body{margin:0;background:#083b49;color:#f7f9fa;font:16px/1.7 Arial,sans-serif}h1,h2,p{margin:0}h1{font-size:30px}h2{font-size:22px;margin:20px 0 12px}main{max-width:1220px;margin:auto;padding:28px}p{margin:10px 0;overflow-wrap:anywhere}.muted{color:#c9e9e9}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.card{border:1px solid #8fced0;border-radius:20px;padding:20px;background:#033240;min-width:0}img{max-width:100%;height:auto;display:block}.crop{width:310px;height:320px;position:relative;overflow:hidden;max-width:100%}.crop img{position:absolute;max-width:none;width:1536px;height:1024px;left:-145px;top:-70px}.symbol{width:310px;height:320px;background:#023d49}.row{display:flex;gap:24px;align-items:center;flex-wrap:wrap}.native{display:grid;justify-items:center;gap:8px}a{color:#ffe076;text-underline-offset:4px;display:inline-block;min-height:44px;padding-block:8px}.headerproof{border-radius:18px;overflow:hidden;margin-top:16px}.pill{display:block;background:#52d8d3;color:#092e39;border-radius:15px;padding:2px 18px;width:max-content;margin:10px 0 4px auto}.source{border-radius:16px}.disclosure{border-top:1px solid #8fced0;margin-top:24px;padding-top:16px;font-size:14px}@media(max-width:700px){main{padding:20px}.pair{grid-template-columns:1fr}.card{padding:16px}.crop{transform-origin:top left}.symbol{max-width:100%;height:auto}h1{font-size:26px}}'''
(D/'proof.css').write_text(css)
head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EgyHealth 360 — board reconstruction</title><link rel="stylesheet" href="proof.css"><link rel="icon" href="data:,"></head><body><main>'
foot='<footer class="disclosure">Sole visual source: SHA-256 0b99fbfb55ba1fcb1276b344fde138b0c48316937bcbad8ea950847bba9ee417. Editable reconstruction, not a new concept. Curves, shading and typography require fidelity review; no pixel-perfect claim. No production implementation or Brand V2 freeze.</footer></main></body></html>'
body='<h1>Approved board → editable reconstruction</h1><p class="muted">Same selected identity: turquoise care forms, gold ribbon and floating head. No earlier logo concept is used.</p><h2>Primary symbol at matched source scale</h2><div class="pair"><section class="card"><h3>Exact approved raster</h3><div class="crop"><img src="source/approved-board.png" alt="Exact source-board primary symbol"></div><p>Source box: x145,y70,width310,height320. CSS viewport only; source bytes unchanged.</p></section><section class="card"><h3>Editable SVG reconstruction</h3><img class="symbol" src="assets/symbol-primary.svg" width="310" height="320" alt="Reconstructed primary vector"><p>Paths and gradients; no embedded raster. Background is a presentation approximation.</p></section></div><h2>Full selected board</h2><img class="source" src="source/approved-board.png" width="1536" height="1024" alt="Unchanged authoritative board"><h2>Reconstructed horizontal lockup</h2><img src="assets/lockup-dark.svg" width="1010" height="350" alt="Full bilingual lockup with both exact taglines"><p>Typography: Inter800/450 and IBM Plex Sans Arabic600 approximation, outlined for self-contained vectors. Letterforms, weights and spacing are not verified as exact.</p><p><a href="index.html">All variants, native sizes and applications</a></p>'
(D/'fidelity.html').write_text(head+body+foot)
body='<h1>EgyHealth 360 — reconstruction proofs</h1><p>Selected reference only. Master geometry is retained in every size; no substitute small-size symbol.</p>'
for v in ['dark','light','mono']:body+=f'<h2>{v.title()} lockup</h2><img src="assets/lockup-{v}.svg" width="1010" height="350" alt="{v} bilingual horizontal lockup">'
body+='<h2>Standalone icons</h2><div class="row">'+''.join(f'<img src="assets/icon-{v}.svg" width="240" height="247" alt="{v} standalone icon">' for v in ['dark','light','mono'])+'</div><h2>App icon and native favicons</h2><div class="row"><img src="assets/app-icon-512.svg" width="256" height="256" alt="512px app artwork displayed at256px">'+''.join(f'<div class="native"><img src="assets/favicon-{s}.svg" width="{s}" height="{s}" alt="Native{s}px favicon"><span>{s}px</span></div>' for s in [32,24,16])+'</div><p><a href="evidence/app-icon-512.png">Actual512px app PNG</a> · <a href="fidelity.html">Source / reconstruction fidelity board</a></p>'
for lang,label in [('ar','العربية'),('en','English')]:body+=f'<h2>{label} NOVA header application</h2><span class="pill" lang="{lang}">{label}</span><div class="headerproof" lang="{lang}" dir="{"rtl" if lang=="ar" else "ltr"}"><img src="assets/nova-header-{lang}.svg" width="1200" height="140" alt="{label} NOVA placement reconstructed from the approved board"></div>'
(D/'index.html').write_text(head+body+foot)
